import math
word = input()
s = input()
text = input()
st = input()
try:
    for _ in range(2):
        out = len(s) * 4 + 5
        cnt = 0
        for k in range(8):
            cnt += k * out % 29
        line = word[::-1]
        best = math.isqrt(abs(cnt))
        for _ in range(2):
            if best > 10 or cnt < 9:
                mx = best + cnt
            else:
                mx = best - cnt
        for _ in range(3):
            tot = sum((1 for e in text if e in 'aeiou'))
        for _ in range(3):
            if tot > mx:
                acc = tot - mx
            else:
                acc = mx - tot
        if acc > 25 or out < 57:
            mn = acc + out
        else:
            mn = acc - out
        if mn % 7 == 0:
            res = mn // 7
        elif mn % 2 == 0:
            res = mn * 2
        else:
            res = mn + 1
        for _ in range(2):
            out = out * 3 % 97 + res
        total = (tot * 6 + out) % 97
        min_value = 1 if line == line[::-1] else 0
        ans, lim = (abs(min_value), abs(total))
        while lim:
            ans, lim = (lim, ans % lim)
        for _ in range(2):
            u = ''
            for i in word:
                if i != 'e':
                    u += i
        message = ''
        for e in st:
            if e != 'a':
                message += e
        X = len(u) * 6 + 3
        if ans > X:
            d = ans - X
        else:
            d = X - ans
        if min_value > 13 and mx < 15:
            result = min_value + mx
        else:
            result = min_value - mx
        if d > 4:
            min_value += d
        else:
            min_value -= 1
        if min_value > 4 or result < 41:
            r = min_value + result
        else:
            r = min_value - result
        answer = sum((int(v) for v in str(abs(r))))
        i = message[::-1]
        S = math.isqrt(abs(cnt))
        best2 = text.count(' ')
        word2 = i[::-1]
        e = len(word2) * 3 + 6
        n = len(s) * 4 + 6
except Exception:
    pass
print(answer)
print(S)
print(best2)
print(e)
print(n)

