    cnt = 0
    for i in range(len(seq)):
        for j in range(len(seq)):
            if i != j:
                if seq[i] > seq[j]:
                    cnt += 1
    mx = 0
    for j in seq:
        if j % 6 == 4:
            mx += j
    total_sum = 0
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if seq[i] + seq[j] > 18:
                total_sum += 1
    out = {}
    for i in seq:
        out[i] = out.get(i, 0) + 1
    total = max(out.values())
    acc = 0
    for i in seq:
        if i % 4 == 1:
            acc += i
    mx = mx * 4 % 1009 + mx
    res = sum(seq)
    min_value, n = (abs(res), abs(cnt))
