            cnt = res - best
        else:
            cnt = best - res
        res = res * 4 % 97 + cnt
        mx = 0
        for e in range(9):
            mx += e * res % 13
        tot = math.factorial(abs(out) % 9)
        ans = math.isqrt(abs(tot))
        total = math.gcd(ans, mx)

        def solve(x):
